import { stdout } from std.io;
class Animal { construct() { } speak(): String { return "..."; } }
class Dog extends Animal {
    tricks: Int32 = 3;
    construct() { super(); }
    #override speak(): String { return "woof" + this.tricks.to_string(); }
}
fn main(): Void {
    mut a: Animal = Dog();
    mut b = a.clone();
    stdout.println(b.speak());
    stdout.println(a is b);
}
